  "recipe.step.apple-baked-skyr-oats.1": "Heat the oven to 180 °C.",
  "recipe.step.apple-baked-skyr-oats.2": "Mix the skyr, oats, egg, apple, raisins, cinnamon and baking powder in a small ovenproof dish.",
  "recipe.step.apple-baked-skyr-oats.3": "Bake for 22–25 minutes until risen and set in the middle.",
  "recipe.step.apple-baked-skyr-oats.4": "Cool for a few minutes before eating.",
  "recipe.step.apple-cinnamon-porridge.1": "Put the oats, soy drink, grated apple and cinnamon in a small pan.",
  "recipe.step.apple-cinnamon-porridge.2": "Simmer for 4–5 minutes, stirring, until thick and creamy.",
  "recipe.step.apple-cinnamon-porridge.3": "Top with the chopped walnuts.",
  "recipe.step.apple-peanut-butter-slices.1": "Core and slice the apple.",
  "recipe.step.apple-peanut-butter-slices.2": "Spread or dip each slice in peanut butter.",
  "recipe.step.apple-peanut-butter-slices.3": "Sprinkle with sunflower seeds.",
  "recipe.step.aubergine-ricotta-parmigiana.1": "Heat the oven to 210 °C. Brush the aubergine with the oil and roast on a tray for 15 minutes.",
  "recipe.step.aubergine-ricotta-parmigiana.2": "Stir the garlic, herbs and seasoning into the passata.",
  "recipe.step.aubergine-ricotta-parmigiana.3": "Layer aubergine, passata and spoonfuls of ricotta in a baking dish, finishing with passata.",
  "recipe.step.aubergine-ricotta-parmigiana.4": "Top with mozzarella and parmesan and bake for 20 minutes until bubbling.",
  "recipe.step.baked-cod-potatoes-peas.1": "Heat the oven to 220 °C (200 °C fan). Toss the potato wedges with most of the oil and salt, and roast for 20 minutes.",
  "recipe.step.baked-cod-potatoes-peas.2": "Push the potatoes aside, add the cod, drizzle with the remaining oil and lemon juice, season, and bake 10–12 minutes until it flakes.",
  "recipe.step.baked-cod-potatoes-peas.3": "Meanwhile, boil the peas for 3 minutes. Serve together with dill.",
  "recipe.step.baked-eggs-white-beans.1": "Heat the oven to 200 °C.",
  "recipe.step.baked-eggs-white-beans.2": "Mix the passata, beans, garlic, oil and paprika in a small baking dish, then stir in the spinach.",
  "recipe.step.baked-eggs-white-beans.3": "Make three hollows and crack in the eggs. Season.",
  "recipe.step.baked-eggs-white-beans.4": "Bake for 12–15 minutes until the whites are set and the yolks still soft.",
  "recipe.step.baked-falafel-pitta.1": "Heat the oven to 200°C. Mash the chickpeas with the spices until they hold together.",
  "recipe.step.baked-falafel-pitta.2": "Shape into 6 small patties, place on a lined tray and bake for 20 minutes, turning once.",
  "recipe.step.baked-falafel-pitta.3": "Whisk the tahini with the lemon juice and a little water.",
  "recipe.step.baked-falafel-pitta.4": "Stuff the pitta with lettuce, tomato and falafel and drizzle with the tahini sauce.",
  "recipe.step.baked-feta-pepper-couscous.1": "Heat the oven to 200 °C. Toss the peppers and tomatoes with the oil and oregano in a baking dish.",
  "recipe.step.baked-feta-pepper-couscous.2": "Set the feta in the middle, sprinkle with chilli and bake for 25 minutes.",
  "recipe.step.baked-feta-pepper-couscous.3": "Meanwhile pour 180 ml boiling water over the couscous, cover for 5 minutes and fluff with a fork.",
  "recipe.step.baked-feta-pepper-couscous.4": "Break up the feta into the vegetables and serve over the couscous with a spoonful of yogurt.",
  "recipe.step.baked-turkey-meatballs-spaghetti.1": "Heat the oven to 200°C. Mix the turkey with the grated onion and half the herbs and roll into 12 meatballs.",
  "recipe.step.baked-turkey-meatballs-spaghetti.2": "Bake in an ovenproof dish for 12 minutes.",
  "recipe.step.baked-turkey-meatballs-spaghetti.3": "Stir the passata with the garlic, oil and remaining herbs, pour over the meatballs and bake 10 minutes more.",
  "recipe.step.baked-turkey-meatballs-spaghetti.4": "Cook the spaghetti, adding the spinach just before draining. Serve with the meatballs and parmesan if using.",
  "recipe.step.banana-blueberry-protein-muffins.1": "Heat the oven to 180 °C and line an 8-hole muffin tin.",
  "recipe.step.banana-blueberry-protein-muffins.2": "Mix the oat flour, protein powder, baking powder and cinnamon.",
  "recipe.step.banana-blueberry-protein-muffins.3": "Whisk the eggs, banana and milk, stir into the dry mix, then fold in the blueberries.",
  "recipe.step.banana-blueberry-protein-muffins.4": "Divide between the cases and bake for 18–20 minutes until a skewer comes out clean.",
  "recipe.step.banana-protein-porridge.1": "Simmer the oats and milk in a small pan for 4–5 minutes, stirring, until creamy.",
  "recipe.step.banana-protein-porridge.2": "Take off the heat and stir in the protein powder with a splash of water until smooth.",
  "recipe.step.banana-protein-porridge.3": "Top with banana and cinnamon.",
  "recipe.step.bean-cheese-quesadilla.1": "Mash the beans roughly with the spices and spread over one tortilla.",
  "recipe.step.bean-cheese-quesadilla.2": "Scatter with pepper, spring onion and cheese, then lay the second tortilla on top.",
  "recipe.step.bean-cheese-quesadilla.3": "Cook in a dry pan over medium heat for about 3 minutes per side until crisp and melted. Cut into wedges.",
  "recipe.step.beef-bean-chilli.1": "Brown the mince in a large pan over high heat, breaking it up, for 5 minutes.",
  "recipe.step.beef-bean-chilli.2": "Add the onion, pepper and garlic and cook 5 minutes. Stir in the spices for 1 minute.",
  "recipe.step.beef-bean-chilli.3": "Add the tomatoes and beans, then simmer uncovered for 25 minutes, stirring now and then.",
  "recipe.step.beef-bean-chilli.4": "Cook the rice according to the packet and serve with the chilli.",
