  "recipe.step.beef-bean-taco-wraps.2": "Add the beans, spices and a splash of water and cook for 3 minutes, lightly crushing some beans.",
  "recipe.step.beef-bean-taco-wraps.3": "Toss the tomato with the lime juice.",
  "recipe.step.beef-bean-taco-wraps.4": "Fill the warmed tortillas with beef, lettuce and tomato and roll up.",
