  "recipe.step.homemade-beans-wholemeal-toast.2": "Simmer for 6 minutes until the sauce thickens, then stir in the spinach to wilt.",
  "recipe.step.homemade-beans-wholemeal-toast.3": "Toast the bread and spoon the beans over the top.",
