  "recipe.step.lamb-cabbage-skillet.3": "Pour in the stock, cover and simmer for 8 minutes.",
  "recipe.step.lamb-cabbage-skillet.4": "Stir in the cabbage, cover again and cook 5 minutes more until everything is tender. Season.",
