  "recipe.step.veggie-eggs-on-rye.2": "Beat the eggs with salt and pepper, pour into the pan and stir gently until just set.",
  "recipe.step.veggie-eggs-on-rye.3": "Toast the rye bread and pile the eggs on top.",
  "recipe.step.warm-squid-chickpea-salad.1": "Pat the squid dry and season with paprika and salt.",
  "recipe.step.warm-squid-chickpea-salad.2": "Heat the oil in a pan until very hot and fry the squid and garlic for 2–3 minutes only.",
  "recipe.step.warm-squid-chickpea-salad.3": "Add the chickpeas for 1 minute to warm through.",
  "recipe.step.warm-squid-chickpea-salad.4": "Tip over the rocket and tomato and squeeze over the lemon.",
  "recipe.step.white-bean-kale-pasta.1": "Cook the pasta, adding the kale for the last 2 minutes. Save a mug of the water, then drain.",
  "recipe.step.white-bean-kale-pasta.2": "Gently fry the garlic and chilli in the oil in the empty pan for 1 minute.",
  "recipe.step.white-bean-kale-pasta.3": "Add the beans and a splash of pasta water and crush a few with a spoon.",
  "recipe.step.white-bean-kale-pasta.4": "Toss in the pasta and kale with the lemon juice and season well.",
  "recipe.step.white-bean-spinach-soup.1": "Soften the onion and garlic in the oil for 4 minutes.",
  "recipe.step.white-bean-spinach-soup.2": "Add the beans, tomatoes, stock and thyme and simmer for 10 minutes.",
  "recipe.step.white-bean-spinach-soup.3": "Mash some of the beans against the side of the pan to thicken the soup.",
  "recipe.step.white-bean-spinach-soup.4": "Stir in the spinach until wilted and season to taste.",
