  "settings.about": "About, formulas & sources",
  "settings.about1rm": "Estimated 1RM uses the Epley formula and is shown only for loaded exercises at 1–10 reps.",
  "settings.aboutBrand": "About {{brand}}",
  "settings.aboutEnergy": "Resting energy: Mifflin–St Jeor equation (Mifflin et al., 1990). Activity factors and goal adjustments are adjustable assumptions.",
  "settings.aboutExercise": "Exercise descriptions are original. No third-party exercise images are used.",
  "settings.aboutFood": "Food values: approximate generic values based on USDA FoodData Central. Always check labels for packaged foods and allergens.",
  "settings.aboutIdea": "{{brand}} is built around a straightforward idea: the work you put into training deserves a clear record. Tracking should feel useful, whether you’re learning your first exercises or working toward a long-held goal.",
  "settings.aboutProtein": "Protein: 1.6–2.2 g per kg of reference bodyweight per day is a practical planning range for muscle gain (Morton et al., 2018, BJSM). 1.8 g/kg is our editable default.",
  "settings.aboutRules": "Programs, progression and nutrition targets are generated by transparent rules. No AI service is involved. The numbers below are adjustable starting points, not medical advice.",
  "settings.aboutSplits": "Training splits, set and rep ranges are product defaults informed by mainstream resistance-training guidance (such as the American College of Sports Medicine’s), not claims of a uniquely optimal program.",
